contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: attempt withdraw of `amount`
    function run(uint256 amount) public payable {
        // record contract balance before
        uint256 contractBalBefore = address(c).balance;

        // attempt withdraw and record whether it reverted
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 contractBalAfter = address(c).balance;

        // If withdraw succeeded, contract's balance must have decreased by at least amount.
        // If it reverted, no guarantee on balances. This asserts the general rule for all inputs.
        assert(reverted || (contractBalBefore >= contractBalAfter && contractBalBefore - contractBalAfter >= amount));
    }

    // accept Ether forwarded from C.transfer when withdraw succeeds
    receive() external payable { }
}

